DROP VIEW "public"."transaction_lines";--> statement-breakpoint
CREATE VIEW "public"."transaction_lines" AS (select t.id, s.id as split_id, t.account_id, t.import_id, t.booking_date, case when s.id is null then t.amount_cents else s.amount_cents end as amount_cents, t.raw_label, t.merchant, case when s.id is null or t.kind = 'transfer' or sc.kind = 'transfer' then t.kind else sc.kind end as kind, case when s.id is null then t.category_id else s.category_id end as category_id, t.needs_review, (t.is_one_off or t.prepaid_item_id is not null) as is_one_off, t.manual, t.prepaid_item_id from transactions t left join transaction_splits s on s.transaction_id = t.id left join categories sc on sc.id = s.category_id);